/// <summary>
/// Get the version number for the provider. Used as part of the overall version number sent to the device
/// </summary>
/// <returns>Version number for the current set of Headers</returns>
public str version()
{        
    TFMFilterAdditions fAdds;
    TFMFilterAdditionsDataBinding fAddDaBi;
    TFMFilterFieldValues fFiVa;
    TFMSearchEDTsToTablesRelation search;

    select firstonly ModifiedDateTime from fAdds order by fAdds.ModifiedDateTime desc;
    select firstonly ModifiedDateTime from fAddDaBi order by fAddDaBi.ModifiedDateTime desc;
    select firstonly ModifiedDateTime from fFiVa order by fFiVa.ModifiedDateTime desc;
    select firstonly ModifiedDateTime from search order by search.ModifiedDateTime desc;

    return 'F'+strKeep(strFmt('%1.%2%3.%4',fAdds.ModifiedDateTime,fAddDaBi.ModifiedDateTime,fFiVa.ModifiedDateTime, search.ModifiedDateTime),'1234567890.');
}
